import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import axios from 'axios';

const Dashboard = () => {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [problems, setProblems] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchProblems();
  }, []);

  const fetchProblems = async () => {
    try {
      const token = localStorage.getItem('token');
      const response = await axios.get('http://localhost:5000/api/problems', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setProblems(response.data.problems || []);
    } catch (error) {
      console.error('Error fetching problems:', error);
    } finally {
      setLoading(false);
    }
  };

  // Stats
  const totalProblems = problems.length;
  const solved = user?.stats?.problemsSolved || 0;
  const attempts = user?.stats?.totalAttempts || 0;
  const successRate = attempts > 0 ? Math.round((solved / attempts) * 100) : 0;

  return (
    <div style={styles.container}>
      {/* ===== SIDEBAR - EXACT TOOFAAN ===== */}
      <div style={styles.sidebar}>
        <div style={styles.sidebarLogo}>⚡ CodeArena</div>
        <div style={styles.sidebarMenu}>
          <div style={styles.sidebarItemActive}>📊 Dashboard</div>
          <div style={styles.sidebarItem}>📋 Assignments</div>
          <div style={styles.sidebarItem}>✅ Completed Tasks</div>
          <div style={styles.sidebarItem}>🏆 Today's Titans</div>
          <div style={styles.sidebarItem}>📌 More ▼</div>
        </div>
        <div style={styles.sidebarBottom}>
          <div style={styles.userInfo}>
            <span style={styles.userAvatar}>👤</span>
            <span style={styles.userName}>{user?.username || 'User'}</span>
          </div>
          <button style={styles.logoutBtn} onClick={() => {
            localStorage.removeItem('token');
            localStorage.removeItem('user');
            navigate('/login');
          }}>
            🚪 Logout
          </button>
        </div>
      </div>

      {/* ===== MAIN CONTENT ===== */}
      <div style={styles.mainContent}>
        
        {/* ===== TOP BAR - EXACT TOOFAAN ===== */}
        <div style={styles.topBar}>
          <div style={styles.topBarLeft}>
            <span style={styles.topBarLogo}>⚡ CodeArena</span>
            <span style={styles.topBarSeparator}>|</span>
            <button onClick={() => navigate('/problems')} style={styles.topBarLink}>Problems</button>
            <span style={styles.topBarSeparator}>|</span>
            <button onClick={() => navigate('/submissions')} style={styles.topBarLink}>Submissions</button>
            <span style={styles.topBarSeparator}>|</span>
            {(user?.role === 'admin' || user?.role === 'setter') && (
              <>
                <button onClick={() => navigate('/create-problem')} style={styles.topBarLink}>Create</button>
                <span style={styles.topBarSeparator}>|</span>
              </>
            )}
            <span style={styles.topBarUser}>{user?.username}</span>
            <span style={styles.topBarSeparator}>|</span>
            <button onClick={() => {
              localStorage.removeItem('token');
              localStorage.removeItem('user');
              navigate('/login');
            }} style={styles.topBarLogout}>
              Logout
            </button>
          </div>
          <div style={styles.topBarRight}>
            <button style={styles.refreshBtn} onClick={() => window.location.reload()}>
              🔄 REFRESH
            </button>
            <span style={styles.weather}>☀️ 29°</span>
          </div>
        </div>

        {/* ===== STATS CARDS - EXACT TOOFAAN ===== */}
        <div style={styles.statsGrid}>
          <div style={styles.statCard}>
            <div style={styles.statNumber}>{totalProblems}</div>
            <div style={styles.statLabel}>Total Problems</div>
          </div>
          <div style={styles.statCard}>
            <div style={styles.statNumber}>{solved}</div>
            <div style={styles.statLabel}>Solved</div>
          </div>
          <div style={styles.statCard}>
            <div style={styles.statNumber}>{attempts}</div>
            <div style={styles.statLabel}>Attempts</div>
          </div>
          <div style={styles.statCard}>
            <div style={styles.statNumber}>{successRate}%</div>
            <div style={styles.statLabel}>Success Rate</div>
          </div>
        </div>

        {/* ===== ASSIGNMENTS - EXACT TOOFAAN ===== */}
        <div style={styles.assignmentsSection}>
          <h2 style={styles.sectionTitle}>📋 Assignments</h2>
          
          <div style={styles.problemGrid}>
            {loading ? (
              <div style={styles.loadingText}>Loading...</div>
            ) : problems.length === 0 ? (
              <div style={styles.emptyState}>No assignments available</div>
            ) : (
              problems.map((problem, index) => (
                <div key={problem._id} style={styles.problemCard}>
                  <div style={styles.programNumber}>
                    PROGRAM-{index + 1}
                  </div>
                  
                  <div style={styles.problemTitle}>
                    {problem.title}
                  </div>
                  
                  <div style={styles.problemMeta}>
                    <span style={styles.problemId}>FS-A1-Audi-2027</span>
                    <span style={styles.problemLab}>LAB</span>
                  </div>
                  
                  <div style={styles.startedInfo}>
                    <span style={styles.startedLabel}>STARTED</span>
                    <span style={styles.startedDate}>
                      on {new Date(problem.createdAt).toLocaleDateString('en-US', { 
                        weekday: 'long',
                        day: 'numeric', 
                        month: 'long', 
                        year: 'numeric' 
                      })}
                    </span>
                  </div>
                  
                  <div style={styles.difficultyRow}>
                    <span style={{
                      ...styles.difficultyBadge,
                      background: problem.difficulty === 'Easy' ? '#28a745' :
                                 problem.difficulty === 'Medium' ? '#ffc107' : '#dc3545',
                      color: problem.difficulty === 'Medium' ? '#333' : 'white',
                    }}>
                      {problem.difficulty || 'Easy'}
                    </span>
                  </div>
                  
                  <button 
                    style={styles.attemptBtn}
                    onClick={() => navigate(`/problems/${problem._id}`)}
                    onMouseEnter={(e) => e.currentTarget.style.background = '#6C63FF'}
                    onMouseLeave={(e) => e.currentTarget.style.background = '#4A3FCF'}
                  >
                    ATTEMPT →
                  </button>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

// ===== EXACT TOOFAAN STYLES =====
const styles = {
  container: {
    display: 'flex',
    minHeight: '100vh',
    background: '#f0f2f5',
    fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
  },

  // ===== SIDEBAR - DARK PURPLE/BLUE =====
  sidebar: {
    width: '250px',
    background: '#1a1a2e',
    color: '#ffffff',
    padding: '24px 20px',
    display: 'flex',
    flexDirection: 'column',
    position: 'fixed',
    height: '100vh',
    boxShadow: '2px 0 20px rgba(0,0,0,0.15)',
    zIndex: 100,
  },
  sidebarLogo: {
    fontSize: '20px',
    fontWeight: 700,
    padding: '0 12px 25px 12px',
    borderBottom: '1px solid rgba(255,255,255,0.08)',
    marginBottom: '16px',
    color: '#ffffff',
  },
  sidebarMenu: {
    display: 'flex',
    flexDirection: 'column',
    gap: '2px',
    flex: 1,
  },
  sidebarItem: {
    padding: '10px 14px',
    borderRadius: '8px',
    cursor: 'pointer',
    fontSize: '14px',
    fontWeight: 500,
    color: 'rgba(255,255,255,0.5)',
    transition: 'all 0.2s',
  },
  sidebarItemActive: {
    padding: '10px 14px',
    borderRadius: '8px',
    cursor: 'pointer',
    fontSize: '14px',
    fontWeight: 600,
    color: '#ffffff',
    background: 'rgba(108, 99, 255, 0.2)',
  },
  sidebarBottom: {
    borderTop: '1px solid rgba(255,255,255,0.08)',
    paddingTop: '16px',
  },
  userInfo: {
    display: 'flex',
    alignItems: 'center',
    gap: '10px',
    padding: '8px 12px',
    borderRadius: '8px',
    background: 'rgba(255,255,255,0.05)',
    marginBottom: '10px',
  },
  userAvatar: {
    fontSize: '18px',
  },
  userName: {
    fontSize: '14px',
    fontWeight: 500,
    color: '#ffffff',
  },
  logoutBtn: {
    width: '100%',
    padding: '8px',
    background: 'rgba(244, 67, 54, 0.15)',
    color: '#ef5350',
    border: 'none',
    borderRadius: '8px',
    cursor: 'pointer',
    fontSize: '13px',
    fontWeight: 500,
    transition: 'all 0.2s',
  },

  // ===== MAIN CONTENT =====
  mainContent: {
    marginLeft: '250px',
    flex: 1,
    padding: '0',
  },

  // ===== TOP BAR - WHITE =====
  topBar: {
    background: '#ffffff',
    padding: '10px 24px',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    borderBottom: '1px solid #e8e8e8',
    flexWrap: 'wrap',
    gap: '8px',
  },
  topBarLeft: {
    display: 'flex',
    alignItems: 'center',
    gap: '10px',
    flexWrap: 'wrap',
  },
  topBarLogo: {
    fontSize: '16px',
    fontWeight: 700,
    color: '#1a1a2e',
  },
  topBarSeparator: {
    color: '#d0d0d0',
    fontSize: '13px',
  },
  topBarLink: {
    background: 'transparent',
    border: 'none',
    color: '#555',
    cursor: 'pointer',
    fontSize: '13px',
    fontWeight: 500,
    padding: '4px 0',
  },
  topBarUser: {
    fontSize: '13px',
    color: '#1a1a2e',
    fontWeight: 600,
  },
  topBarLogout: {
    background: 'transparent',
    border: 'none',
    color: '#ef5350',
    cursor: 'pointer',
    fontSize: '13px',
    fontWeight: 500,
    padding: '4px 0',
  },
  topBarRight: {
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
  },
  refreshBtn: {
    padding: '4px 14px',
    background: '#6C63FF',
    color: 'white',
    border: 'none',
    borderRadius: '4px',
    fontSize: '11px',
    fontWeight: 600,
    cursor: 'pointer',
    letterSpacing: '0.3px',
  },
  weather: {
    fontSize: '14px',
    fontWeight: 500,
    color: '#333',
  },

  // ===== STATS CARDS - WHITE =====
  statsGrid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(160px, 1fr))',
    gap: '16px',
    padding: '20px 24px',
  },
  statCard: {
    background: '#ffffff',
    padding: '16px 20px',
    borderRadius: '10px',
    boxShadow: '0 1px 4px rgba(0,0,0,0.06)',
    textAlign: 'center',
  },
  statNumber: {
    fontSize: '26px',
    fontWeight: 700,
    color: '#1a1a2e',
  },
  statLabel: {
    fontSize: '13px',
    color: '#888',
    marginTop: '4px',
  },

  // ===== ASSIGNMENTS SECTION =====
  assignmentsSection: {
    padding: '0 24px 24px 24px',
  },
  sectionTitle: {
    fontSize: '18px',
    fontWeight: 600,
    color: '#1a1a2e',
    marginBottom: '16px',
  },

  problemGrid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))',
    gap: '16px',
  },

  // ===== PROBLEM CARD - WHITE WITH BORDER =====
  problemCard: {
    background: '#ffffff',
    borderRadius: '10px',
    padding: '18px 22px',
    border: '1px solid #e8e8e8',
    boxShadow: '0 1px 4px rgba(0,0,0,0.04)',
    display: 'flex',
    flexDirection: 'column',
    gap: '6px',
  },
  programNumber: {
    fontSize: '13px',
    fontWeight: 700,
    color: '#6C63FF',
    letterSpacing: '0.3px',
  },
  problemTitle: {
    fontSize: '17px',
    fontWeight: 600,
    color: '#1a1a2e',
  },
  problemMeta: {
    display: 'flex',
    gap: '10px',
    alignItems: 'center',
    fontSize: '12px',
  },
  problemId: {
    color: '#666',
    fontWeight: 500,
  },
  problemLab: {
    color: '#6C63FF',
    fontWeight: 600,
    background: 'rgba(108, 99, 255, 0.08)',
    padding: '0 10px',
    borderRadius: '4px',
    fontSize: '10px',
    letterSpacing: '0.3px',
  },
  startedInfo: {
    display: 'flex',
    flexDirection: 'column',
    padding: '6px 0',
    borderTop: '1px solid #f0f0f0',
    borderBottom: '1px solid #f0f0f0',
    margin: '2px 0',
  },
  startedLabel: {
    fontSize: '10px',
    fontWeight: 600,
    color: '#999',
    letterSpacing: '0.5px',
  },
  startedDate: {
    fontSize: '13px',
    color: '#333',
  },
  difficultyRow: {
    display: 'flex',
    gap: '6px',
    marginTop: '2px',
  },
  difficultyBadge: {
    padding: '2px 12px',
    borderRadius: '12px',
    fontSize: '10px',
    fontWeight: 600,
    display: 'inline-block',
  },
  attemptBtn: {
    width: '100%',
    padding: '10px',
    background: '#4A3FCF',
    color: 'white',
    border: 'none',
    borderRadius: '8px',
    fontSize: '13px',
    fontWeight: 600,
    cursor: 'pointer',
    transition: 'all 0.2s',
    letterSpacing: '0.3px',
    marginTop: '4px',
  },
  loadingText: {
    textAlign: 'center',
    padding: '40px',
    color: '#666',
    gridColumn: '1 / -1',
  },
  emptyState: {
    textAlign: 'center',
    padding: '40px',
    color: '#666',
    gridColumn: '1 / -1',
  },
};

export default Dashboard;
